private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int index = i;
    while (index < bb.limit()) {
        int b = bb.get(index++);
        if (b < 0) {
            // Invalid octet
            return -1;
        }
        if (b < 0x80) {
            // ASCII character
            sb.append((char) b);
        } else if (b < 0xC0) {
            // Invalid octet
            return -1;
        } else if (b < 0xE0) {
            // Two-octet sequence
            int b1 = bb.get(index++);
            if (b1 < 0x80 || b1 > 0xBF) {
                // Invalid octet
                return -1;
            }
            sb.append((char) ((b & 0x1F) << 6 | b1 & 0x3F));
        } else if (b < 0xF0) {
            // Three-octet sequence
            int b1 = bb.get(index++);
            int b2 = bb.get(index++);
            if (b1 < 0x80 || b1 > 0xBF || b2 < 0x80 || b2 > 0xBF) {
                // Invalid octet
                return -1;
            }
            sb.append((char) ((b & 0x0F) << 12 | (b1 & 0x3F) << 6 | b2 & 0x3F));
        } else {
            // Four-octet sequence
            int b1 = bb.get(index++);
            int b2 = bb.get(index++);
            int b3 = bb.get(index++);
            if (b1 < 0x80 || b1 > 0xBF || b2 < 0x80 || b2 > 0xBF || b3 < 0x80 || b3 > 0xBF) {
                // Invalid octet
                return -1;
            }
            sb.append((char) ((b & 0x07) << 18 | (b1 & 0x3F) << 12 | (b2 & 0x3F) << 6 | b3 & 0x3F));
        }
    }
    return index;
}
```
